ControlPropertyState.AutoRuleBindingString:
With(
    {
        RegistroFirma: LookUp(
            'Asistencia por sesion',
            ID_Sesion = Text(varSesionGlobal.ID) && 
            N_Empleado = Value(ThisItem.N_Empleado) 
        )
    },
    
    If(
        RegistroFirma.Asistencia = true,
        Icon.Check,
        Icon.Cancel
    )
)
